#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    int n;
    cin >> n;

    if (n <= 0) return 0;

    vector<int> arr(n);
    for (int& value : arr) cin >> value;

    sort(arr.begin(), arr.end());

    if (n <= 2) {
        cout << arr[0];
        return 0;
    }

    int maxValue = -1;
    int maxIndex = 1;

    for (int i = 1; i < n - 1; ++i) {
        int value = max(arr[i] - arr[0], arr[n - 1] - arr[i]);
        if (value > maxValue) {
            maxValue = value;
            maxIndex = i;
        }
    }

    cout << arr[maxIndex];
    return 0;
}

